import java.io.*;import java.util.*;import org.jf.dexlib2.*;import org.jf.dexlib2.iface.*;import org.jf.dexlib2.iface.instruction.*;import org.jf.dexlib2.iface.reference.*;
public class VerifyInvocationContracts {
 static String key(MethodReference m){return m.getDefiningClass()+"->"+m.getName()+m.getParameterTypes()+m.getReturnType();}
 public static void main(String[] args)throws Exception{
  List<DexFile> files=new ArrayList<>();Map<String,Method> methods=new HashMap<>();for(String arg:args){DexFile d=DexFileFactory.loadDexFile(new File(arg),Opcodes.forApi(28));files.add(d);for(ClassDef c:d.getClasses())for(Method m:c.getMethods())methods.put(key(m),m);}
  int checked=0,bad=0,counts=0;for(DexFile d:files)for(ClassDef c:d.getClasses())for(Method m:c.getMethods()){if(m.getImplementation()==null)continue;int offset=0;for(Instruction i:m.getImplementation().getInstructions()){if(i instanceof ReferenceInstruction){Reference r=((ReferenceInstruction)i).getReference();if(r instanceof MethodReference&&i.getOpcode().name().startsWith("INVOKE_")){MethodReference reference=(MethodReference)r;boolean directStatic=i.getOpcode()==Opcode.INVOKE_STATIC||i.getOpcode()==Opcode.INVOKE_STATIC_RANGE;int expected=directStatic?0:1;for(CharSequence type:reference.getParameterTypes())expected+=(type.toString().equals("J")||type.toString().equals("D"))?2:1;int actual=((VariableRegisterInstruction)i).getRegisterCount();counts++;if(expected!=actual){bad++;System.out.println(c.getType()+"->"+m.getName()+" @"+Integer.toHexString(offset)+" argument words="+actual+" expected="+expected+" target="+key(reference));}Method target=methods.get(key(reference));if(target!=null){checked++;boolean stat=(target.getAccessFlags()&8)!=0,staticCall=i.getOpcode()==Opcode.INVOKE_STATIC||i.getOpcode()==Opcode.INVOKE_STATIC_RANGE;if(stat!=staticCall){bad++;System.out.println(c.getType()+"->"+m.getName()+" @"+Integer.toHexString(offset)+" "+i.getOpcode()+" target="+key(target)+" static="+stat);}}}}offset+=i.getCodeUnits();}}
  System.out.println("All invocation arity checks="+counts+", defined-target invocation checks="+checked+", dispatch mismatches="+bad);if(checked<1000)throw new AssertionError("No adequate call coverage");if(bad!=0)throw new AssertionError("Invalid static/instance dispatch");
 }
}
